    :root { --book-circle-image:url("data:image/webp;base64,"); --color-primary:#172B4D; --color-primary-blue:#00bfd3; --color-accent:#F4C542; --color-background:var(--color-background); --color-surface:#F5F6F7; --color-text:#222222; --color-text-muted:#6B7280; --color-border:#E5E7EB; --sidebar-width:290px; --sidebar-header-bg:#ffffff; --sidebar-nav-start:#1ba6c1; --sidebar-nav-end:#0f8099; --sidebar-active-bg:rgba(255,255,255,.22); --sidebar-active-border:rgba(255,255,255,.45); --sidebar-hover-bg:rgba(255,255,255,.12); --sidebar-gold:#f5a623; --sidebar-text:#ffffff; --sidebar-divider:rgba(255,255,255,.3); --phone-panel-border:#B9E8EF; --phone-panel-bg-start:#F4FCFE; --phone-panel-bg-end:#EAF8FB; --phone-ink:#172B4D; --phone-body:#334155; --phone-muted:#475569; --phone-icon:#00899C; --phone-icon-bg:#DDF3F5; --phone-number-bg:#D2F0F2; --phone-number-text:#176C78; --phone-example:#135E70; --phone-divider:#B9E8EF; --phone-reminder-border:#C7EAF0; --phone-reminder-bg:rgba(255,255,255,.72); --phone-reminder-divider:#A8DDE6; }
    html {
      overflow-y: scroll;
      scrollbar-gutter: stable;
