    const discountGuidelines = { cashDisc: '10%', countries: { CA: { prefix: 'CA$', flag: 'ca', invoice: [2199, 3649, 6699, 7399, 9499, 12999], free: [330, 547, 1005, 1110, 1425, 1950] }, AU: { prefix: 'AU$', flag: 'au', invoice: [2399, 3899, 7099, 7799, 10199, 13999], free: [360, 585, 1065, 1170, 1530, 2100] }, US: { prefix: 'US$', flag: 'us', invoice: [1749, 2999, 5499, 6199, 7999, 11499], free: [262, 450, 825, 930, 1200, 1725] }, UK: { prefix: '\u00A3', flag: 'gb', invoice: [1249, 2099, 4099, 4299, 5899, 7999], free: [187, 315, 615, 645, 885, 1200] }, EU: { prefix: '\u20AC', flag: 'eu', invoice: [1499, 2499, 4899, 5099, 6899, 9899], free: [225, 375, 735, 765, 1035, 1485] } } };
    const bookCreditGuide = { countries: { CA: { currency: 'CAD', symbol: '$', flag: 'https://flagcdn.com/ca.svg' }, AU: { currency: 'AUD', symbol: '$', flag: 'https://flagcdn.com/au.svg' }, US: { currency: 'USD', symbol: '$', flag: 'https://flagcdn.com/us.svg' }, UK: { currency: 'GBP', symbol: '\u00A3', flag: 'https://flagcdn.com/gb.svg' }, EU: { currency: 'EUR', symbol: '\u20AC', flag: 'https://flagcdn.com/eu.svg' } }, packages: [{ name: 'Standard package', credit: { CAD: 50, AUD: 55, USD: 40, GBP: 35, EUR: 40 } }, { name: 'Professional package', credit: { CAD: 100, AUD: 115, USD: 80, GBP: 70, EUR: 80 } }, { name: 'All-inclusive package', credit: { CAD: 150, AUD: 175, USD: 120, GBP: 100, EUR: 120 } }, { name: 'Traditional package', credit: { CAD: 200, AUD: 250, USD: 170, GBP: 150, EUR: 170 } }, { name: "Children's Standard package", credit: { CAD: 50, AUD: 55, USD: 40, GBP: 35, EUR: 40 } }, { name: "Children's Professional/Illustrated", credit: { CAD: 100, AUD: 115, USD: 80, GBP: 70, EUR: 80 } }, { name: "Children's All-inclusive", credit: { CAD: 150, AUD: 175, USD: 120, GBP: 100, EUR: 120 } }, { name: "Children's Traditional", credit: { CAD: 200, AUD: 250, USD: 170, GBP: 150, EUR: 170 } }] };
