    const discountMarketChoices = [{ market: 'AUS', code: 'AU', flag: 'https://flagcdn.com/au.svg' }, { market: 'USA', code: 'US', flag: 'https://flagcdn.com/us.svg' }, { market: 'CAN', code: 'CA', flag: 'https://flagcdn.com/ca.svg' }, { market: 'UKI', code: 'UK', flag: 'https://flagcdn.com/gb.svg' }, { market: 'EU', code: 'EU', flag: 'https://flagcdn.com/eu.svg' }];
    function discountMarketPicker() { const current = discountMarketChoices.find(option => option.market === activeMarket) || discountMarketChoices[2]; return `<div id="marketDropdown" class="relative"><button id="marketSelect" type="button" aria-haspopup="true" aria-expanded="false" aria-label="Selected country: ${current.code}" class="inline-flex items-center gap-2 rounded-md border border-[#E5E7EB] bg-white px-2.5 py-2 text-sm font-semibold text-[#172B4D] hover:bg-[#F5F6F7] focus:outline-none focus:ring-2 focus:ring-aus"><img src="${current.flag}" alt="" class="h-4 w-6 object-cover"><span>${current.code}</span><i data-lucide="chevron-down" class="h-4 w-4"></i></button><div id="marketOptions" role="menu" class="absolute right-0 top-full z-20 mt-1 hidden min-w-24 overflow-hidden rounded-md border border-[#E5E7EB] bg-white py-1 shadow-lg">${discountMarketChoices.map(option => `<button type="button" role="menuitemradio" aria-checked="${option.market === activeMarket}" class="marketOption flex w-full items-center gap-2 px-3 py-2 text-left text-sm font-medium ${option.market === activeMarket ? 'bg-aus text-white' : 'text-[#222222] hover:bg-[#F5F6F7]'}" data-market="${option.market}"><img src="${option.flag}" alt="" class="h-4 w-6 object-cover"><span>${option.code}</span></button>`).join('')}</div></div>`; }
    function renderDiscountRows() { const body = document.querySelector('#discountGuidelineRows'); if (!body) return; const country = discountGuidelines.countries[discountCountryByMarket[activeMarket]] || discountGuidelines.countries.CA; const format = value => `${country.prefix}${new Intl.NumberFormat('en-US').format(value)}`; body.innerHTML = country.invoice.map((invoice, index) => `<tr class="border-t border-blue-50"><td class="px-3 py-2 align-top">${format(invoice)}</td><td class="px-3 py-2 align-top">${discountGuidelines.cashDisc}</td><td class="px-3 py-2 align-top">${format(country.free[index])}</td></tr>`).join(''); const button = document.querySelector('#marketSelect'); const current = discountMarketChoices.find(option => option.market === activeMarket); if (button && current) { button.setAttribute('aria-label', `Selected country: ${current.code}`); button.querySelector('img').src = current.flag; button.querySelector('span').textContent = current.code; } document.querySelectorAll('.marketOption').forEach(option => { const selected = option.dataset.market === activeMarket; option.setAttribute('aria-checked', String(selected)); option.classList.toggle('bg-aus', selected); option.classList.toggle('text-white', selected); option.classList.toggle('text-[#222222]', !selected); }); }
    function creditMarketPicker() { const country = bookCreditGuide.countries[activeCreditCountry]; return `<div id="creditMarketDropdown" class="relative"><button id="creditMarketSelect" type="button" aria-haspopup="true" aria-expanded="false" aria-label="Selected country: ${activeCreditCountry}" class="inline-flex items-center gap-2 rounded-md border border-[#E5E7EB] bg-white px-2.5 py-2 text-sm font-semibold text-[#172B4D] hover:bg-[#F5F6F7] focus:outline-none focus:ring-2 focus:ring-aus"><img src="${country.flag}" alt="" class="h-4 w-6 object-cover"><span>${activeCreditCountry}</span><i data-lucide="chevron-down" class="h-4 w-4"></i></button><div id="creditMarketOptions" role="menu" class="absolute right-0 top-full z-20 mt-1 hidden min-w-24 overflow-hidden rounded-md border border-[#E5E7EB] bg-white py-1 shadow-lg">${creditCountryChoices.map(code => { const option = bookCreditGuide.countries[code]; return `<button type="button" role="menuitemradio" aria-checked="${code === activeCreditCountry}" class="creditMarketOption flex w-full items-center gap-2 px-3 py-2 text-left text-sm font-medium ${code === activeCreditCountry ? 'bg-aus text-white' : 'text-[#222222] hover:bg-[#F5F6F7]'}" data-country="${code}"><img src="${option.flag}" alt="" class="h-4 w-6 object-cover"><span>${code}</span></button>`; }).join('')}</div></div>`; }
    function renderBookCreditRows() { const body = document.querySelector('#bookCreditRows'); if (!body) return; const country = bookCreditGuide.countries[activeCreditCountry] || bookCreditGuide.countries.CA; body.innerHTML = bookCreditGuide.packages.map(item => `<tr class="border-t border-blue-50"><td class="px-3 py-2 align-top">${item.name}</td><td class="px-3 py-2 align-top">${country.symbol}${new Intl.NumberFormat('en-US').format(item.credit[country.currency])}</td></tr>`).join(''); const button = document.querySelector('#creditMarketSelect'); if (button) { button.setAttribute('aria-label', `Selected country: ${activeCreditCountry}`); button.querySelector('img').src = country.flag; button.querySelector('span').textContent = activeCreditCountry; } document.querySelectorAll('.creditMarketOption').forEach(option => { const selected = option.dataset.country === activeCreditCountry; option.setAttribute('aria-checked', String(selected)); option.classList.toggle('bg-aus', selected); option.classList.toggle('text-white', selected); option.classList.toggle('text-[#222222]', !selected); }); }
    let custom = JSON.parse(localStorage.getItem('aus-custom') || '[]'), customNav = JSON.parse(localStorage.getItem('aus-navigation-links') || '[]'), saved = JSON.parse(localStorage.getItem('aus-saved') || '[]'), recent = JSON.parse(localStorage.getItem('aus-recent') || '[]'), filter = 'All', savedMode = false, expanded = {}, activePage = 0;
    const consultationView = document.querySelector('#pageContent').innerHTML;
