    function spielsPage() {
      const styles = `<style>
    :root { --color-primary:#172B4D; --color-primary-blue:#00bfd3; --color-accent:#F4C542; --color-background:var(--color-background); --color-surface:#F5F6F7; --color-text:#222222; --color-text-muted:#6B7280; --color-border:#E5E7EB; }
