    let writersJourneyDocumentPromise = null;
    function writersJourneyPage() { return '<section id="writersJourneyMount" class="app-page" data-theme="light"></section>' }
    async function loadWritersJourneyDocument() {
      const mount = document.querySelector('#writersJourneyMount');
      if (!mount) return;
      if (!writersJourneyDocumentPromise) {
        writersJourneyDocumentPromise = (async () => {
          const binary = atob(document.querySelector('#masterclassPagePayload').textContent.trim());
          const bytes = Uint8Array.from(binary, character => character.charCodeAt(0));
          const compressed = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
          return new Response(compressed).text();
        })();
      }
      const html = await writersJourneyDocumentPromise;
      if (!mount.isConnected) return;
      mount.style.cssText = 'display:block;width:100%;max-width:none;margin:0;padding:0;background:transparent;border:0;box-shadow:none';
