      const root = mount.attachShadow({ mode: 'open' });
      source.querySelectorAll('link[rel="stylesheet"]').forEach(link => root.append(link.cloneNode(true)));
      const style = document.createElement('style');
      const sourceStyles = Array.from(source.querySelectorAll('style'), node => node.textContent).join('\n')
        .replace(/:root/g, ':host')
        .replace(/\bhtml\s*\{/g, ':host {')
        .replace(/\bbody\s*\{/g, ':host {');
      style.textContent = sourceStyles + `
