.app-hero { position:relative; overflow:hidden; display:flex; width:100%; min-height:146px; flex-direction:column; justify-content:center; gap:10px; margin:0 0 24px; border:1px solid #E5E7EB; border-radius:20px; background:linear-gradient(110deg,#FFFFFF 0%,#FBFEFE 48%,#DDF5F8 72%,#62BFDC 100%); padding:24px 160px 24px 32px; box-shadow:0 12px 28px rgba(25,91,171,.08); }
.app-hero::before { content:''; position:absolute; z-index:1; top:50%; right:24px; width:110px; height:110px; transform:translateY(-50%); border:3px solid #fff; border-radius:50%; background:#fff var(--book-circle-image) center/cover no-repeat; box-shadow:0 4px 14px rgba(21,38,43,.18); }
.app-hero::after { content:''; position:absolute; z-index:0; inset:0; width:auto; background:linear-gradient(90deg,transparent 58%,rgba(83,190,218,.25)); pointer-events:none; }
.app-hero > * { position:relative; z-index:2; }
