 .journey-subnav { position:sticky; top:0; z-index:31; display:flex; width:calc(100% + 3rem); margin:0 -1.5rem 24px; padding:0 1rem; overflow-x:auto; overscroll-behavior-x:contain; border-top:1px solid #E5E7EB; border-bottom:1px solid #DBEAFE; background:#fff; box-shadow:0 6px 18px rgba(25,91,171,.06); scrollbar-width:none; }
 .journey-subnav::-webkit-scrollbar { display:none; }
 .journey-subnav a { position:relative; display:flex; min-width:max-content; flex:1; align-items:center; justify-content:center; min-height:52px; border-right:1px solid #E5E7EB; padding:0 15px; color:#172B4D; font-size:13px; font-weight:600; text-align:center; text-decoration:none; white-space:nowrap; }
 .journey-subnav a:last-child { border-right:0; }
 .journey-subnav a::after { position:absolute; right:12px; bottom:0; left:12px; height:3px; border-radius:3px 3px 0 0; background:transparent; content:''; }
 .journey-subnav a.active,.journey-subnav a:hover { color:#00aeca; }
 .journey-subnav a.active::after { background:#00bfd3; }
 @media(max-width:767px) { .journey-subnav { width:calc(100% + 28px); margin-right:-14px; margin-left:-14px; padding:0 4px; } .journey-subnav a { flex:none; padding:0 14px; } } @media(max-width:380px) { .journey-subnav { width:calc(100% + 20px); margin-right:-10px; margin-left:-10px; } }
.app-hero .eyebrow { margin:0; color:#00BFD3; font-size:12px; font-weight:700; letter-spacing:.18em; line-height:1.2; text-transform:uppercase; }
.app-hero h1 { margin:4px 0 0; width:auto; margin-left:0; color:#172B4D; font-family:Manrope,sans-serif; font-size:30px; font-weight:800; line-height:1.2; text-align:left; }
.app-hero .lede { max-width:64ch; margin:0; color:#6B7280; font-size:14px; line-height:1.5; }
.agenda,.flow,.stop,.checklist,.who,.prep,.g,.lp,.g-price,.g-never { border-color:#E5E7EB; border-radius:12px; box-shadow:0 7px 18px rgba(25,91,171,.07); }
.wrap > .who { display:flex; align-self:stretch; width:100%; max-width:none; box-sizing:border-box; }
